<?php $buscadorId=$buscadorId??'catalogo'; $buscadorPlaceholder=$buscadorPlaceholder??'Buscar por título o descripción…'; ?>
<div class="d-flex justify-content-center mb-4"><div class="input-group" style="max-width:620px"><span class="input-group-text bg-white"><i class="bi bi-search"></i></span><input type="search" class="form-control" id="<?=htmlspecialchars($buscadorId)?>" placeholder="<?=htmlspecialchars($buscadorPlaceholder)?>" autocomplete="off"><button type="button" class="btn btn-outline-secondary d-none" id="<?=$buscadorId?>Limpiar">Limpiar</button></div></div>
<p class="text-muted text-center d-none" id="<?=$buscadorId?>Vacio">No encontramos resultados. Prueba con otras palabras.</p>
<script>(function(){const input=document.getElementById(<?=json_encode($buscadorId)?>),clear=document.getElementById(<?=json_encode($buscadorId.'Limpiar')?>),empty=document.getElementById(<?=json_encode($buscadorId.'Vacio')?>);function norm(v){return v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}function run(){const q=norm(input.value);let n=0;document.querySelectorAll('.pf-item-buscable').forEach(el=>{const ok=!q||norm(el.dataset.busqueda||'').includes(q);el.classList.toggle('d-none',!ok);if(ok)n++});clear.classList.toggle('d-none',!q);empty.classList.toggle('d-none',n>0)}input.addEventListener('input',run);clear.onclick=()=>{input.value='';run();input.focus()}})();</script>
